1	/**
2	 * Programmatic Drizzle migration runner using drizzle-orm/node-postgres migrator.
3	 *
4	 * This script properly checks the `drizzle.__drizzle_migrations` table and only
5	 * applies pending migrations — unlike `drizzle-kit migrate` v0.31.x which ignores
6	 * the tracking table and tries to re-apply ALL SQL files from scratch.
7	 *
8	 * Usage:
9	 *   DATABASE_URL=<direct_neon_url> tsx scripts/db-migrate.ts
10	 *
11	 * In CI (production.yml):
12	 *   DATABASE_URL: ${{ secrets.DIRECT_DATABASE_URL_PROD }}
13	 *   run: tsx scripts/db-migrate.ts
14	 */
15	
16	import * as crypto from 'node:crypto';
17	import * as fs from 'node:fs';
18	import * as path from 'node:path';
19	import * as dotenv from 'dotenv';
20	import { drizzle } from 'drizzle-orm/node-postgres';
21	import { migrate } from 'drizzle-orm/node-postgres/migrator';
22	import { Pool } from 'pg';
23	
24	dotenv.config();
25	
26	type MigrationJournal = {
27	  entries: Array<{ idx: number; tag: string; when: number }>;
28	};
29	
30	type MigrationQueryResult<T extends Record<string, unknown>> = {
31	  rowCount: number | null;
32	  rows: T[];
33	};
34	
35	type MigrationQueryClient = {
36	  query<T extends Record<string, unknown> = Record<string, unknown>>(
37	    queryText: string,
38	    values?: unknown[],
39	  ): Promise<MigrationQueryResult<T>>;
40	  release(): void;
41	};
42	
43	type MigrationPool = {
44	  connect(): Promise<MigrationQueryClient>;
45	};
46	
47	function requireDatabaseUrl(): string {
48	  const databaseUrl = process.env.DATABASE_URL;
49	  if (!databaseUrl) {
50	    console.error('❌ DATABASE_URL is not set.');
51	    process.exit(1);
52	  }
53	
54	  if (databaseUrl.includes('-pooler.')) {
55	    console.error(
56	      '❌ DATABASE_URL appears to be a pooled Neon URL (contains "-pooler.").',
57	    );
58	    console.error(
59	      '   Drizzle migrations require a DIRECT (unpooled) connection.',
60	    );
61	    console.error(
62	      '   Remove "-pooler" from the hostname and remove channel_binding=require.',
63	    );
64	    process.exit(1);
65	  }
66	
67	  return databaseUrl;
68	}
69	
70	/**
71	 * Compute the hash drizzle-orm stores for a migration file.
72	 * Drizzle uses SHA-256 of the raw file content (not split statements).
73	 * Returns null if the SQL file does not exist on disk.
74	 */
75	function migrationHash(tag: string): string | null {
76	  const filePath = path.join('drizzle', `${tag}.sql`);
77	  if (!fs.existsSync(filePath)) return null;
78	  const content = fs.readFileSync(filePath).toString();
79	  return crypto.createHash('sha256').update(content).digest('hex');
80	}
81	
82	export async function repairWorkOrderSoftDeleteMigration(
83	  pool: MigrationPool,
84	  journal: MigrationJournal,
85	): Promise<boolean> {
86	  const tag296 = '0296_wo_soft_delete';
87	  const entry296 = journal.entries.find((e) => e.tag === tag296);
88	  if (!entry296) return false;
89	
90	  const hash296 = migrationHash(tag296);
91	  if (hash296 === null) {
92	    console.log(`⚠️  Skipping 0296 repair: SQL file not found on disk`);
93	    return false;
94	  }
95	
96	  const client = await pool.connect();
97	  let inTransaction = false;
98	  try {
99	    const tracked296 = await client.query(
100	      'SELECT 1 FROM drizzle.__drizzle_migrations WHERE hash = $1 LIMIT 1',
101	      [hash296],
102	    );
103	    if ((tracked296.rowCount ?? 0) > 0) return false;
104	
105	    const workOrdersExists = await client.query(
106	      `SELECT 1 FROM information_schema.tables
107	       WHERE table_schema = 'public' AND table_name = 'work_orders' LIMIT 1`,
108	    );
109	    if ((workOrdersExists.rowCount ?? 0) === 0) return false;
110	
111	    const existingColumns = await client.query<{ column_name: string }>(
112	      `SELECT column_name
113	       FROM information_schema.columns
114	       WHERE table_schema = 'public'
115	         AND table_name = 'work_orders'
116	         AND column_name = ANY($1::text[])`,
117	      [
118	        [
119	          'is_deleted',
120	          'deleted_at',
121	          'deleted_by',
122	          'delete_reason',
123	          'delete_notes',
124	        ],
125	      ],
126	    );
127	    if ((existingColumns.rowCount ?? 0) === 0) return false;
128	
129	    console.log(
130	      '🔧 work_orders soft-delete columns partially applied — repairing 0296',
131	    );
132	    await client.query('BEGIN');
133	    inTransaction = true;
134	    await client.query(
135	      `ALTER TABLE "work_orders" ADD COLUMN IF NOT EXISTS "is_deleted" boolean`,
136	    );
137	    await client.query(
138	      `UPDATE "work_orders" SET "is_deleted" = false WHERE "is_deleted" IS NULL`,
139	    );
140	    await client.query(
141	      `ALTER TABLE "work_orders" ALTER COLUMN "is_deleted" SET DEFAULT false`,
142	    );
143	    await client.query(
144	      `ALTER TABLE "work_orders" ALTER COLUMN "is_deleted" SET NOT NULL`,
145	    );
146	    await client.query(
147	      `ALTER TABLE "work_orders" ADD COLUMN IF NOT EXISTS "deleted_at" timestamp with time zone`,
148	    );
149	    await client.query(
150	      `ALTER TABLE "work_orders" ADD COLUMN IF NOT EXISTS "deleted_by" uuid`,
151	    );
152	    await client.query(
153	      `ALTER TABLE "work_orders" ADD COLUMN IF NOT EXISTS "delete_reason" text`,
154	    );
155	    await client.query(
156	      `ALTER TABLE "work_orders" ADD COLUMN IF NOT EXISTS "delete_notes" text`,
157	    );
158	    await client.query(`
159	      DO $$ BEGIN
160	        ALTER TABLE "work_orders"
161	          ADD CONSTRAINT "work_orders_deleted_by_users_id_fk"
162	          FOREIGN KEY ("deleted_by") REFERENCES "public"."users"("id") ON DELETE no action ON UPDATE no action;
163	      EXCEPTION WHEN duplicate_object THEN null;
164	      END $$
165	    `);
166	    await client.query(
167	      `INSERT INTO drizzle.__drizzle_migrations (hash, created_at)
168	       VALUES ($1, $2)`,
169	      [hash296, entry296.when],
170	    );
171	    await client.query('COMMIT');
172	    inTransaction = false;
173	    console.log(`🔧 Marked ${tag296} as applied`);
174	    return true;
175	  } catch (err) {
176	    if (inTransaction) {
177	      await client.query('ROLLBACK');
178	    }
179	    throw err;
180	  } finally {
181	    client.release();
182	  }
183	}
