185	/**
186	 * Pre-flight repair: if a migration's SQL objects already exist in the DB but
187	 * the migration isn't recorded in __drizzle_migrations, insert the row so
188	 * drizzle-orm's migrate() skips it instead of failing with "already exists".
189	 *
190	 * This handles environments where a migration was applied manually or via an
191	 * earlier CI run that crashed before the tracking row was written.
192	 */
193	async function repairMissingTrackingRows(pool: Pool): Promise<void> {
194	  const journal = JSON.parse(
195	    fs.readFileSync(path.join('drizzle', 'meta', '_journal.json'), 'utf-8'),
196	  ) as { entries: Array<{ idx: number; tag: string; when: number }> };
197	
198	  // Pairs: [table_to_probe, tag] — if the table exists and the migration isn't
199	  // tracked we insert it.  Add new rows here whenever a future migration hits
200	  // the same "already exists" error.
201	  const probes: Array<{ table: string; tag: string }> = [
202	    {
203	      table: 'course_standalone_instructors',
204	      tag: '0021_add_standalone_assignments_and_curricula_image',
205	    },
206	    // 0036__pre_push_check, 0050__pre_push_check, 0057__pre_push_check, and
207	    // 0067__pre_push_check are drizzle-kit snapshot migrations that were generated
208	    // but never committed to git (their SQL files were cleaned up before merge).
209	    // On any DB that has already progressed past these indices, they must be
210	    // marked as applied so migrate() skips them instead of crashing with ENOENT.
211	    // The stub SQL files in drizzle/ allow the hash to be computed and tracked.
212	    // We use 'student_invoices' (always exists by idx 4) as the sentinel table.
213	    {
214	      table: 'student_invoices',
215	      tag: '0036__pre_push_check',
216	    },
217	    {
218	      table: 'student_invoices',
219	      tag: '0050__pre_push_check',
220	    },
221	    {
222	      table: 'schedule_standby_entries',
223	      tag: '0067__pre_push_check',
224	    },
225	    // 0057__pre_push_check is a drizzle-kit snapshot migration that duplicates
226	    // CREATE TABLE for referrals, referral_payment_schedules,
227	    // referral_program_settings, school_payment_methods, sms_logs, and
228	    // widget_template_installs WITHOUT IF NOT EXISTS.  On any DB where 0052–0055
229	    // already ran, 0057 fails with "relation already exists" and blocks the
230	    // migration runner, preventing all subsequent migrations from applying.
231	    // If the referrals table exists (proving 0055 already ran), mark 0057 as
232	    // applied so the runner skips it.
233	    {
234	      table: 'referrals',
235	      tag: '0057__pre_push_check',
236	    },
237	    // 0074_lms_guide_assignments creates the lms_guide_assignments table.
238	    // If a prior drizzle-kit push already created the table but the migration
239	    // tracking row is absent, the runner would fail with "relation already exists"
240	    // and block 0075+.  Probe the table and mark as applied if it exists.
241	    {
242	      table: 'lms_guide_assignments',
243	      tag: '0074_lms_guide_assignments',
244	    },
245	    // 0075_add_packet_template_customization creates packet_template_items and
246	    // packet_template_sections.  Same pattern as above.
247	    {
248	      table: 'packet_template_items',
249	      tag: '0075_add_packet_template_customization',
250	    },
251	    // 0081_add_dashboard_layouts creates the dashboard_layouts table.
252	    // The migration has been in the journal since April 2025 but was not
253	    // applied to all environments (dev DB shows absent table despite the
254	    // tracking row existing in some states).  0092_ensure_dashboard_layouts
255	    // is the canonical fix; this probe handles databases where 0081 ran
256	    // successfully and the table exists but 0081 is not tracked.
257	    {
258	      table: 'dashboard_layouts',
259	      tag: '0081_add_dashboard_layouts',
260	    },
261	    // 0116_add_crm_contact_notes and 0117_crm_contact_appointments were
262	    // committed with `when` timestamps that caused the Drizzle migration
263	    // runner to skip them in some environments (the `when` values sat between
264	    // already-applied migrations in sorted order and were never executed).
265	    // Both tables are missing from the dev database, causing all Marketing Hub
266	    // contact write operations (Notes tab, Appointments tab) to fail with a
267	    // PostgreSQL undefined_table error → HTTP 500.
268	    // 0123_ensure_crm_notes_and_appointments creates both tables idempotently.
269	    // These probes mark 0116 and 0117 as applied on any database where the
270	    // tables were already created by 0123 (or by a prior manual fix), so the
271	    // runner does not attempt to re-apply the original migrations.
272	    {
273	      table: 'crm_contact_notes',
274	      tag: '0116_add_crm_contact_notes',
275	    },
276	    {
277	      table: 'crm_contact_appointments',
278	      tag: '0117_crm_contact_appointments',
279	    },
280	    // 0123_ensure_crm_notes_and_appointments was committed with `when`=2025-04-07
281	    // (wrong year), so it is also skipped by the migration runner on environments
282	    // where 0115/0124 (2026-dated) are already applied.  Migration 0126 carries
283	    // the correct 2026 timestamp and creates the tables idempotently.  This probe
284	    // marks 0123 as applied once the tables exist, preventing a duplicate-run
285	    // attempt if the timestamp ordering issue is ever corrected upstream.
286	    {
287	      table: 'crm_contact_notes',
288	      tag: '0123_ensure_crm_notes_and_appointments',
289	    },
290	    // 0132_fuel_invoices was committed with `when`=1743957942367 (≈April 2025),
291	    // but migrations 0130 and 0131 carry March 2026 timestamps.  Drizzle's runner
292	    // sorts pending migrations by `when`; because 0132's value sits before the
293	    // already-applied 0130/0131 entries, the runner treats it as applied and
294	    // silently skips it.  0133_ensure_fuel_invoices carries a correct 2026
295	    // timestamp and creates the table idempotently.  This probe marks 0132 as
296	    // applied on any database where the table already exists (created by 0133 or
297	    // by a prior manual fix), preventing a duplicate-run attempt.
298	    {
299	      table: 'fuel_invoices',
300	      tag: '0132_fuel_invoices',
301	    },
302	    // 0175_postmortem_action_items creates the postmortem_action_items table.
303	    // Uses CREATE TABLE IF NOT EXISTS and CREATE INDEX IF NOT EXISTS, so it's
304	    // safe to re-run, but mark as applied to avoid unnecessary execution.
305	    {
306	      table: 'postmortem_action_items',
307	      tag: '0175_postmortem_action_items',
308	    },
309	    // 0314_course_hour_buckets creates product_fees, product_hour_buckets, and
310	    // adds pricing_strategy/quoted_price/invoice_render_mode to products.
311	    // If the tables exist but the migration isn't tracked (partial apply or prior
312	    // drizzle-kit push), mark it as applied so migrate() skips it.
313	    {
314	      table: 'product_fees',
315	      tag: '0314_course_hour_buckets',
316	    },
317	    // 0341_external_references and 0342_slippery_black_knight can be present in
318	    // databases that received the idempotent 0340 reconciliation migration first.
319	    // If the objects exist but the later tracking rows are absent, Drizzle retries
320	    // non-idempotent CREATE TABLE statements from 0342 and blocks all newer work.
321	    {
322	      table: 'external_references',
323	      tag: '0341_external_references',
324	    },
325	    {
326	      table: 'external_financial_references',
327	      tag: '0342_slippery_black_knight',
328	    },
329	  ];
330	
331	  for (const { table, tag } of probes) {
332	    const entry = journal.entries.find((e) => e.tag === tag);
333	    if (!entry) continue;
334	
335	    // Skip if the SQL file no longer exists (e.g., sentinel files that were cleaned up)
336	    const probeFilePath = path.join('drizzle', `${tag}.sql`);
337	    if (!fs.existsSync(probeFilePath)) continue;
338	
339	    const hash = migrationHash(tag);
340	    // If the SQL file is missing we cannot compute a hash — skip this probe.
341	    // The stub SQL files in drizzle/ should always exist; this guard prevents
342	    // a crash if one is accidentally deleted in the future.
343	    if (hash === null) {
344	      console.log(`⚠️  Skipping probe for ${tag}: SQL file not found on disk`);
345	      continue;
346	    }
347	
348	    // Check if migration is already tracked
349	    const tracked = await pool.query(
350	      'SELECT 1 FROM drizzle.__drizzle_migrations WHERE hash = $1 LIMIT 1',
351	      [hash],
352	    );
353	    if ((tracked.rowCount ?? 0) > 0) continue;
354	
355	    // Check if the relation already exists (migration was applied but not tracked).
356	    // Use pg_class instead of information_schema.tables so this matches the
357	    // condition that makes CREATE TABLE fail with "relation already exists",
358	    // even when the relation is found through a non-standard search_path.
359	    const exists = await pool.query(
360	      `SELECT 1
361	       FROM pg_class c
362	       JOIN pg_namespace n ON n.oid = c.relnamespace
363	       WHERE c.relname = $1
364	         AND n.nspname NOT IN ('pg_catalog', 'information_schema')
365	       LIMIT 1`,
366	      [table],
367	    );
368	    if ((exists.rowCount ?? 0) === 0) continue;
369	
370	    // Table exists but migration not tracked — insert the tracking row
371	    await pool.query(
372	      `INSERT INTO drizzle.__drizzle_migrations (hash, created_at)
373	       VALUES ($1, $2)`,
374	      [hash, entry.when],
375	    );
376	    console.log(
377	      `🔧 Marked migration as applied (table already existed): ${tag}`,
378	    );
379	  }
380	
381	  // Column-based probes: check if a specific column exists in a table.
382	  // Used when a migration adds columns that were already applied to a DB branch
383	  // via a different code path (e.g. manual SQL or a parallel branch merge).
384	  const columnProbes: Array<{
385	    column: string;
386	    table: string;
387	    tag: string;
388	  }> = [
389	    {
390	      column: 'task_grades',
391	      table: 'schedule_events',
392	      tag: '0026_add_grade_fields_to_schedule_events',
393	    },
394	    // POA module fields — may have been applied via the orphan 0041_add_poa_module_fields.sql
395	    // before the journal entry for 0041_add_poa_module_columns was created.
396	    {
397	      column: 'title',
398	      table: 'plans_of_action',
399	      tag: '0041_add_poa_module_columns',
400	    },
401	    // Hobbs/tach columns — may have been applied manually or via direct DB repair
402	    // (e.g. emergency fix when 0042_repair_missing_poa_schedule_columns failed to run).
403	    {
404	      column: 'hobbs_out',
405	      table: 'schedule_events',
406	      tag: '0042_repair_missing_poa_schedule_columns',
407	    },
408	    // student_invoices.metadata — added in 0035, but 0039_salty_violations was also
409	    // modified after its original apply to include this column. If metadata already
410	    // exists, mark 0035 as applied so migrate() doesn't re-attempt it.
411	    {
412	      column: 'metadata',
413	      table: 'student_invoices',
414	      tag: '0035_add_metadata_to_student_invoices',
415	    },
416	    // referral_program_settings.share_link_token — added by 0056_add_referral_enhancements.
417	    // PR #455 deleted 0055_add_referral_program.sql which caused the migration runner to
418	    // crash (ENOENT) before reaching 0056. On any DB where 0057__pre_push_check already
419	    // created the column via drizzle-kit push, mark 0056 as applied so the runner skips it.
420	    {
421	      column: 'share_link_token',
422	      table: 'referral_program_settings',
423	      tag: '0056_add_referral_enhancements',
424	    },
425	    {
426	      column: 'notify_on_activate',
427	      table: 'schedule_events',
428	      tag: '0073_standby_aircraft_events',
429	    },
430	    {
431	      column: 'activated_at',
432	      table: 'schedule_events',
433	      tag: '0073_standby_aircraft_events',
434	    },
435	    {
436	      column: 'activated_by',
437	      table: 'schedule_events',
438	      tag: '0073_standby_aircraft_events',
439	    },
440	    // instructor_id on document_metadata — added by 0104_instructor_document_scope.
441	    // 0104 was merged with a backdated 'when' timestamp (1743292800001) lower than
442	    // 0103 (1743345787000), causing Drizzle's migrate() to skip it entirely.
443	    // The SQL uses ADD COLUMN without IF NOT EXISTS, so applyTimestampSkippedMigrations
444	    // fails with "already exists" on DBs where the column was created via drizzle-kit push.
445	    // This probe handles "column exists but migration not tracked" cleanly.
446	    // applyTimestampSkippedMigrations then handles "column absent, migration not tracked".
447	    // Without this column, countPendingByLocationForInstructors throws on every request,
448	    // the API catches it silently and returns {counts: {}}, and the amber Review Docs
449	    // button never appears on the instructor roster.
450	    {
451	      column: 'instructor_id',
452	      table: 'document_metadata',
453	      tag: '0104_instructor_document_scope',
454	    },
455	    // display_order on training_courses — added by 0159_training_courses_display_order.
456	    // The DIRECT_DATABASE_URL_PROD secret pointed to the dev branch (ep-fancy-queen)
457	    // instead of production (ep-aged-sea), so migrations 145-163 ran against dev.
458	    // The column may exist on prod from a partial run or manual fix, but the tracking
459	    // row is missing. 0159 uses bare ADD COLUMN (no IF NOT EXISTS), so migrate() fails
460	    // with "already exists". This probe marks it as applied if the column is present.
461	    {
462	      column: 'display_order',
463	      table: 'training_courses',
464	      tag: '0159_training_courses_display_order',
465	    },
466	    // resource_taxable on product_hour_buckets — added by 0315_taxable_hour_buckets.
467	    // 0315 was committed with a backdated `when` timestamp (1746403200000, ≈May 2025),
468	    // so applyTimestampSkippedMigrations picks it up. The column probe handles the case
469	    // where 0315 was applied to this DB path (columns exist) but not tracked.
470	    {
471	      column: 'resource_taxable',
472	      table: 'product_hour_buckets',
473	      tag: '0315_taxable_hour_buckets',
474	    },
475	    // corrective_action on maintenance_discrepancies — added by 0294_discrepancy_faa_resolve_fields.
476	    // The demo Neon branch had these columns applied (via prior sync or manual SQL) but the
477	    // migration tracking row is missing. migrate() fails with "column already exists" on every
478	    // nightly Demo Daily Refresh since 2026-05-05.
479	    {
480	      column: 'corrective_action',
481	      table: 'maintenance_discrepancies',
482	      tag: '0294_discrepancy_faa_resolve_fields',
483	    },
484	  ];
485	
486	  for (const { column, table, tag } of columnProbes) {
487	    const entry = journal.entries.find((e) => e.tag === tag);
488	    if (!entry) continue;
489	
490	    const hash = migrationHash(tag);
491	    if (hash === null) {
492	      console.log(`⚠️  Skipping column probe for ${tag}: SQL file not found on disk`);
493	      continue;
494	    }
495	
496	    const tracked = await pool.query(
497	      'SELECT 1 FROM drizzle.__drizzle_migrations WHERE hash = $1 LIMIT 1',
498	      [hash],
499	    );
500	    if ((tracked.rowCount ?? 0) > 0) continue;
501	
502	    const exists = await pool.query(
503	      `SELECT 1 FROM information_schema.columns
504	       WHERE table_schema = 'public' AND table_name = $1 AND column_name = $2 LIMIT 1`,
505	      [table, column],
506	    );
507	    if ((exists.rowCount ?? 0) === 0) continue;
508	
509	    await pool.query(
510	      `INSERT INTO drizzle.__drizzle_migrations (hash, created_at)
511	       VALUES ($1, $2)`,
512	      [hash, entry.when],
513	    );
514	    console.log(
515	      `🔧 Marked migration as applied (column already existed): ${tag}`,
516	    );
517	  }
518	
519	  // ── Special repair: 0296_wo_soft_delete partially applied on demo ──
520	  //
521	  // The demo Neon branch has hit the same drift pattern as earlier maintenance
522	  // migrations: at least part of the work_orders soft-delete schema exists, but
523	  // the 0296 tracking hash is absent. The raw migration uses bare ADD COLUMN
524	  // statements, so migrate() fails on the first existing column before the demo
525	  // seed can run. If any 0296 column is present, normalize the full column set
526	  // idempotently and then track the migration.
527	  await repairWorkOrderSoftDeleteMigration(pool, journal);
528	
529	  // ── Special repair: 0039_salty_violations was modified after its original apply ──
530	  //
531	  // History:
532	  //   v1: Original 0039 applied to production DB (student_certificates,
533	  //       student_flags, user.banned columns).
534	  //   v2: File modified to add `student_invoices.metadata` (no IF NOT EXISTS) —
535	  //       changed hash. PR #398 added this repair block to handle existing DBs.
536	  //   v3: File modified again to use `ADD COLUMN IF NOT EXISTS` for metadata —
537	  //       changed hash again. This makes 0039 safe for fresh DBs where 0035
538	  //       already ran (0035 also adds metadata without IF NOT EXISTS).
539	  //
540	  // For existing DBs (student_certificates already exists) and current on-disk
541	  // hash untracked: apply metadata column if missing, then track current hash.
542	  // For fresh DBs: drizzle migrate() runs 0035 then 0039 in order; the IF NOT
543	  // EXISTS in v3 prevents the duplicate-column failure.
