14	const ROOT = path.resolve(__dirname, '..');
15	const JOURNAL_PATH = path.join(ROOT, 'drizzle', 'meta', '_journal.json');
16	const OUTPUT_DIR = path.join(ROOT, 'src', 'generated');
17	const OUTPUT_PATH = path.join(OUTPUT_DIR, 'migration-manifest.ts');
18	
19	function main() {
20	  // Read and parse the journal
21	  if (!fs.existsSync(JOURNAL_PATH)) {
22	    console.error(`[generate-migration-manifest] Journal not found at ${JOURNAL_PATH}`);
23	    process.exit(1);
24	  }
25	
26	  const raw = fs.readFileSync(JOURNAL_PATH, 'utf-8');
27	  const journal = JSON.parse(raw);
28	
29	  if (!journal.entries || !Array.isArray(journal.entries) || journal.entries.length === 0) {
30	    console.error('[generate-migration-manifest] Journal has no entries');
31	    process.exit(1);
32	  }
33	
34	  const count = journal.entries.length;
35	  const latestTag = journal.entries[journal.entries.length - 1].tag;
36	
37	  // Ensure output directory exists
38	  if (!fs.existsSync(OUTPUT_DIR)) {
39	    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
40	  }
41	
42	  // Write the manifest
43	  const content = [
44	    '// AUTO-GENERATED by scripts/generate-migration-manifest.js — do not edit',
45	    `export const MIGRATION_COUNT = ${count};`,
46	    `export const LATEST_MIGRATION = '${latestTag}';`,
47	    '', // trailing newline
48	  ].join('\n');
49	
50	  fs.writeFileSync(OUTPUT_PATH, content, 'utf-8');
51	
52	  console.log(
53	    `[generate-migration-manifest] Wrote ${OUTPUT_PATH} — ${count} migrations, latest: ${latestTag}`,
